float sdfEraser(float z){
    return  abs(mod(z,1.)-.5)-0.4;
}


float sdf(in vec3 p) {
    //return min(min(min(abs(p.y- .5),abs(p.x+ .5)),abs(p.y+ .5)),abs(p.x- .5))-0.01;
    return max(min(min(min(abs(p.y- .5),abs(p.x+ .5)),abs(p.y+ .5)),abs(p.x- .5))-0.05,-sdfEraser(p.z));

}


mat3 rotationZ(float angle) {
    return mat3(
        vec3(cos(angle), -sin(angle), 0.0),
        vec3(sin(angle),  cos(angle), 0.0),
        vec3(0.0, 0.0, 1.0)
    );
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec2 uv = (2. *  fragCoord - iResolution.xy)/iResolution.y;


    vec3 ro = vec3(1.*cos(iTime),1.*sin(iTime),iTime),
         rt = vec3(0.,0.,5.+iTime);

    if(iMouse.z > .01){ro=vec3(0.,0.,iTime);rt = vec3(0.,0.,10.+iTime);;}

    vec3 z = normalize(rt-ro);
    vec3 y = vec3(0.,1.,0.);
    vec3 x = cross(y,z);
    y = cross(z,x);
    mat3 cam = mat3(x,y,z) * rotationZ(iTime); 
    vec3 rd = normalize(cam * vec3(uv,1.));

    vec3 p;
    float t =  0.;
    for(int i=0;i<999 && t < 999.;i++){
        p = ro + rd * t;
        float d = sdf(p);
        if(abs(d)<1e-3){
            fragColor = mix(vec4(1.,0.,0.,1.),vec4(1.,1.,1.,1.),1.-1./sqrt(sqrt(t))); 

            return;
        }else{
            t+=d;
        }
    }
    fragColor = vec4(1.);

}
